#!/usr/bin/env node
'use strict';
/* Generates the contract constants for the SDKs from contract.json.
 *   node generate.js          write every target whose SDK folder exists
 *   node generate.js --check  fail when contract.json breaks a rule or a generated file is out of date */

const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const contract = JSON.parse(fs.readFileSync(path.join(__dirname, 'contract.json'), 'utf8'));

/** Rule check: no attribute the Collector would delete or the encoders would drop as a secret. */
function problems(c) {
  const out = [];
  // The JSON keeps the (?i) prefix the Collector and the Kotlin regex use; JS takes the flag separately.
  const regex = p => new RegExp(p.replace(/^\(\?i\)/, ''), 'i');
  const deleted = regex(c.collectorDeletedKeyPattern);
  const secret = regex(c.secretPattern);
  const names = new Set(Object.values(c.attributes).flat());
  for (const name of names) {
    if (deleted.test(name) && !(name in c.knownViolations)) out.push(`${name}: deleted by the Collector (collectorDeletedKeyPattern)`);
    if (secret.test(name)) out.push(`${name}: dropped by the encoders (secretPattern)`);
    if (c.reserved.includes(name)) out.push(`${name}: reserved for the platform`);
  }
  for (const name of Object.keys(c.knownViolations)) if (!names.has(name)) out.push(`${name}: knownViolations entry without attribute`);
  for (const stage of [...c.setupStages.app, ...c.setupStages.relay]) {
    if (!c.labels.call_setup.includes(stage)) out.push(`${stage}: setup stage missing from labels.call_setup`);
  }
  return out;
}

const header = 'Generated by lt-telemetry-contract/generate.js from contract.json. Do not edit.';
const str = s => JSON.stringify(s);
const constName = s => s.toUpperCase().replace(/[^A-Z0-9]+/g, '_');
const camel = s => s.replace(/[._-]([a-z0-9])/g, (_, c) => c.toUpperCase());

function kotlin(c) {
  const list = xs => `listOf(${xs.map(str).join(', ')})`;
  const map = (o, v) => `mapOf(\n${Object.entries(o).map(([k, x]) => `        ${str(k)} to ${v(x)},`).join('\n')}\n    )`;
  return `// ${header}
package com.tswork.lt.telemetry

object Contract {
    const val VERSION = ${c.version}
    object Body {
${c.bodies.map(b => `        const val ${constName(b)} = ${str(b)}`).join('\n')}
    }
    val BODIES = ${list(c.bodies)}
    val SEVERITIES = ${list(c.severities)}
    val ERROR_DOMAINS = ${list(c.errorDomains)}
    val APP_SETUP_STAGES = ${list(c.setupStages.app)}
    val RELAY_SETUP_STAGES = ${list(c.setupStages.relay)}
    val THERMAL_LEVELS = ${list(c.thermalLevels)}
    /** label -> reasons; an empty list means the reason is free text (engine state names and similar). */
    val LABELS: Map<String, List<String>> = ${map(c.labels, list)}
    val ATTRIBUTES: Map<String, List<String>> = ${map(c.attributes, list)}
    val ATTRIBUTE_PREFIXES = ${list(c.attributePrefixes)}
    val RESERVED = ${list(c.reserved)}
    const val COLLECTOR_DELETED_KEY_PATTERN = ${str(c.collectorDeletedKeyPattern).replace(/\$/g, '\\$')}
    const val SECRET_PATTERN = ${str(c.secretPattern)}
}
`;
}

function swift(c) {
  const list = xs => `[${xs.map(str).join(', ')}]`;
  const map = (o, v) => `[\n${Object.entries(o).map(([k, x]) => `        ${str(k)}: ${v(x)},`).join('\n')}\n    ]`;
  return `// ${header}

public enum Contract {
    public static let version = ${c.version}
    public enum Body {
${c.bodies.map(b => `        public static let ${camel(b)} = ${str(b)}`).join('\n')}
    }
    public static let bodies = ${list(c.bodies)}
    public static let severities = ${list(c.severities)}
    public static let errorDomains = ${list(c.errorDomains)}
    public static let appSetupStages = ${list(c.setupStages.app)}
    public static let relaySetupStages = ${list(c.setupStages.relay)}
    public static let thermalLevels = ${list(c.thermalLevels)}
    /// label -> reasons; an empty list means the reason is free text (engine state names and similar).
    public static let labels: [String: [String]] = ${map(c.labels, list)}
    public static let attributes: [String: [String]] = ${map(c.attributes, list)}
    public static let attributePrefixes = ${list(c.attributePrefixes)}
    public static let reserved = ${list(c.reserved)}
    public static let collectorDeletedKeyPattern = ${str(c.collectorDeletedKeyPattern)}
    public static let secretPattern = ${str(c.secretPattern)}
}
`;
}

function js(c) {
  const { version, bodies, severities, errorDomains, setupStages, thermalLevels, labels, attributes, attributePrefixes, reserved,
    collectorDeletedKeyPattern, secretPattern } = c;
  const data = { version, bodies, severities, errorDomains, setupStages, thermalLevels, labels, attributes, attributePrefixes, reserved,
    collectorDeletedKeyPattern, secretPattern };
  return `'use strict';
// ${header}
module.exports = Object.freeze(${JSON.stringify(data, null, 2)});
`;
}

const targets = [
  { dir: 'lt-telemetry-android', file: 'src/main/java/com/tswork/lt/telemetry/Contract.kt', render: kotlin },
  { dir: 'LtTelemetry-ios', file: 'Sources/LtTelemetry/Contract.swift', render: swift },
  { dir: 'lt-telemetry-node', file: 'src/contract.js', render: js },
];

function main(args) {
  const check = args.includes('--check');
  const found = problems(contract);
  if (found.length) { console.error(found.map(p => `contract: ${p}`).join('\n')); return 1; }
  let stale = 0;
  for (const t of targets) {
    if (!fs.existsSync(path.join(root, t.dir))) continue;
    const file = path.join(root, t.dir, t.file);
    const text = t.render(contract);
    const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
    if (current === text) continue;
    if (check) { console.error(`out of date: ${path.relative(root, file)} (run node lt-telemetry-contract/generate.js)`); stale++; continue; }
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, text);
    console.log(`wrote ${path.relative(root, file)}`);
  }
  return stale ? 1 : 0;
}

if (require.main === module) process.exitCode = main(process.argv.slice(2));
module.exports = { problems, kotlin, swift, js };
